    /**
     * 根据 userid 和 externalUserid，找到对应客户备注 根据 addTag 和 removeTag，修改对应 corpwx_tags
     *
     * @param accCodeTable accCodeTable
     * @param map          map
     * @return boolean
     */
    static boolean updateCorpWxTagByUserIdAndExternalUserId(AccCodeTable accCodeTable, Map<String, Object> map) {
        String userid = (String) map.getOrDefault("userid", "");
        String externalUserid = (String) map.getOrDefault("external_userid", "");
        List<String> addTag = (List<String>) map.getOrDefault("add_tag", new ArrayList<>());
        List<String> removeTag = (List<String>) map.getOrDefault("remove_tag", new ArrayList<>());

        String selectSql = "select corpwx_tags from " +
                followUserTablePrefix + accCodeTable.getAccCode() +
                " where corpwx_userid = '" + userid + "'" +
                " and corpwx_external_userid = '" + externalUserid + "'";
        log.info("selectSql: " + selectSql);
        String corpWxTags;
        try {
            corpWxTags = accCodeTable.getJt().queryForObject(selectSql, String.class);
        } catch (DataAccessException e) {
            corpWxTags = "";
        }

        // 将 corpWxTags 转为 ArrayList
        List<String> corpWxTagsList = new ArrayList<>();
        if (StringUtils.isNotBlank(corpWxTags)) {
            // 不可使用 Arrays.asList()：其 add 会抛出异常
            corpWxTagsList = Arrays.stream(corpWxTags.split(",")).collect(Collectors.toList());
        }

        // 若标签添加、删除相同，则该标签不起作用（相互抵消）
        // duplicateItemList 保存 addTag 和 removeTag 中重复的数据
        ArrayList<String> duplicateItemList = new ArrayList<>();
        for (String removeTagItem : removeTag) {
            if (addTag.contains(removeTagItem)) {
                addTag.remove(removeTagItem);
                duplicateItemList.add(removeTagItem);
            }
        }
        for (String duplicateItem : duplicateItemList) {
            removeTag.remove(duplicateItem);
        }

        // 为 corpWxTagsList 添加 addTag
        for (String addTagItem : addTag) {
            boolean find = false;
            // 判断 addTagItem 是否存在 corpWxTagsList 中，避免重复添加
            for (String corpWxTagItem : corpWxTagsList) {
                if (Objects.equals(addTagItem, corpWxTagItem)) {
                    find = true;
                    break;
                }
            }
            // 不存在，添加到 corpWxTagsList 中
            if (!find) {
                corpWxTagsList.add(addTagItem);
            }
        }

        // 为 corpWxTagsList 删除 removeTag
        ArrayList<String> needRemoveTagList = new ArrayList<>();
        for (String removeTagItem : removeTag) {
            // removeTagItem 存在于 corpWxTagsList 中，添加到 needRemoveTagList 中
            if (corpWxTagsList.contains(removeTagItem)) {
                needRemoveTagList.add(removeTagItem);
            }
        }
        for (String needRemoveItem : needRemoveTagList) {
            corpWxTagsList.remove(needRemoveItem);
        }

        String corpWxTagsListString = String.join(",", corpWxTagsList);
        String updateSql = "update " +
                followUserTablePrefix + accCodeTable.getAccCode() +
                " set corpwx_tags = '" + corpWxTagsListString + "'" +
                " where corpwx_userid = '" + userid + "'" +
                " and corpwx_external_userid = '" + externalUserid + "'";
        log.info("update sql: " + updateSql);

        return accCodeTable.getJt().update(updateSql) > 0;
    }

    static String getCorpwxUserIdByCorpwxExternalUserid(String externalUserid, AccCodeTable accCodeTable) {
        String sql = "select corpwx_userid from " +
