    /**
     * 根据偏移量，返回客户列表（默认返回 10 条）
     * @param accCodeTable
     * @param unionId
     * @param offset
     * @return
     */
    static List<String> findTagNamesByPageWithUnionId(AccCodeTable accCodeTable, String unionId, int offset) {
        List<String> res=new ArrayList<>();
        CorpwxTagOperator tagOperator = SpringContextUtil.getBean("theCorpwxTagOperator", CorpwxTagOperator.class);
        CorpwxCustomerOperator customerOperator = SpringContextUtil.getBean("theCorpwxCustomerOperator", CorpwxCustomerOperator.class);
        //根据unionId获取userId
        String userIdByUnionId = customerOperator.getCorpwxCustomerUserIdByUnionId(unionId, accCodeTable);
        int start = offset * 10;
        String tagSelectSql = "select * from " +
                followUserTablePrefix + accCodeTable.getAccCode() +
                " where corpwx_external_userid = '"+userIdByUnionId+"'"+
                " limit " +
                start + "," + 10;

        log.info("customerSelectSql: " + tagSelectSql);

        List<CorpwxFollowUser> followUsers = accCodeTable.getJt()
                .query(tagSelectSql, BeanPropertyRowMapper.newInstance(CorpwxFollowUser.class));
        if(followUsers!=null && followUsers.size()>0){
            CorpwxFollowUser corpwxFollowUser = followUsers.get(0);
            String corpwxTags = corpwxFollowUser.getCorpwxTags();
            String[] tagIds = corpwxTags.split(",");
            log.info(tagIds);
            for (String tagId : tagIds) {
                String tagNameByTagId = tagOperator.findTagNameByTagId(accCodeTable, tagId);
                res.add(tagNameByTagId);
            }
            return res;
        }else{
            log.info("cant find any result");
            return null;
        }
    }
