    String lockKey = "pay:lock:" + request.getOrderNo();
    RLock lock = redisson.getLock(lockKey);

    boolean locked = lock.tryLock(3, 30, TimeUnit.SECONDS);
    if (!locked) {
        return Result.fail("支付处理中，请勿重复提交");
    }

    try {
        //检查支付状态
