@Scheduled(cron = "0 0 2 * * ?")  // 每天凌晨2点
public void reconcile() {
    // 查找支付中超过30分钟的订单
    List<Order> pendingOrders = orderMapper.findTimeout();

    for (Order order : pendingOrders) {
        // 查第三方支付结果
        PayResult result = thirdPartyPay.query(order.getNo());

        if (result.isPaid()) {
            // 补偿处理
            orderService.updateStatus(order.getId(), OrderStatus.PAID);
        } else {
            // 关闭订单
            orderService.updateStatus(order.getId(), OrderStatus.CLOSED);
        }
    }
}

