  @RestController
  @RequestMapping("/api")
  public class PopController {

      @Autowired
      private AreaService areaService;  // 区域服务

      // 节点配置
      private static final Map<String, String> REGION_NODES = Map.of(
          "guangzhou", "gz-node1.example.com",
          "shanghai", "sh-node1.example.com",
          "beijing", "bj-node1.example.com"
      );

      @GetMapping("/pop")
      public Map<String, Object> pop(HttpServletRequest request) {
          String clientIp = getClientIp(request);

          // 从区域数据库查询
          String region = areaService.getRegionByIp(clientIp);

          // 返回该区域的节点
          String nodeAddress = REGION_NODES.getOrDefault(region, "gz-node1.example.com");

          return Map.of(
              "success", true,
              "region", region,
              "node", nodeAddress,
              "clientIp", clientIp
          );
      }

      private String getClientIp(HttpServletRequest request) {
          String ip = request.getHeader("X-Forwarded-For");
          if (ip == null) ip = request.getHeader("X-Real-IP");
          if (ip == null) ip = request.getRemoteAddr();
          return ip.split(",")[0].trim();
      }
  }

