  public class IoTClient {

      private String deviceId = "device_12345";
      private String bestNode = null;

      public void start() {
          if (bestNode == null) {
              // 首次：请求 /pop 获取最佳节点
              bestNode = requestPop();
          }

          // 连接到 /message
          connectToMessage(bestNode);
