      /**
       * 请求 /pop 接口
       */
      private String requestPop() {
          try {
              URL url = new URL("http://api.example.com/api/pop");
              HttpURLConnection conn = (HttpURLConnection) url.openConnection();
              conn.setConnectTimeout(3000);

              BufferedReader reader = new BufferedReader(
                  new InputStreamReader(conn.getInputStream()));
              String response = reader.lines().collect(Collectors.joining());

              JSONObject json = JSON.parseObject(response);
              String node = json.getString("node");

              System.out.println("分配节点: " + node);
              return node;
          } catch (Exception e) {
              return "default.example.com";
          }
      }

      /**
       * 连接到 /message（建立 Socket）
       */
      private void connectToMessage(String nodeAddress) {
          try {
              // Socket 连接到 9000 端口（/message 路径）
              String[] parts = nodeAddress.split(":");
              String host = parts[0];
              int port = parts.length > 1 ? Integer.parseInt(parts[1]) : 9000;

              Node serverNode = new Node(host, port);
              clientChannelContext = Tio.connect(clientGroupContext, serverNode);

              // 发送认证
              IoTPacket authPacket = IoTPacket.createAuth(deviceId);
              Tio.send(clientChannelContext, authPacket);

              System.out.println("连接成功: " + nodeAddress);
          } catch (Exception e) {
              System.err.println("连接失败: " + e.getMessage());
          }
      }

      /**
       * 重连
       */
      public void reconnect() {
          // 直接连接到之前的节点（无需再请求 /pop）
          connectToMessage(bestNode);
      }
  }

